<section class="mx-auto max-w-md px-4 py-16 sm:px-6"><flux:card><flux:heading size="xl">Sign in</flux:heading><flux:text class="mt-2">Access your orders and saved addresses.</flux:text><form wire:submit="authenticate" class="mt-6 grid gap-5"><flux:input wire:model="email" type="email" label="Email" autocomplete="email" autofocus /><flux:input wire:model="password" type="password" label="Password" autocomplete="current-password" viewable /><flux:checkbox wire:model="remember" label="Remember me" /><flux:button type="submit" variant="primary" class="w-full">Sign in</flux:button></form><p class="mt-6 text-center text-sm">New here? <a class="underline" href="{{ route('storefront.account.register') }}">Create an account</a></p></flux:card></section>
